import { join } from "node:path";

import {
  Document,
  FileBlob,
  Presentation,
  PresentationFile,
  SpreadsheetFile,
  Workbook,
} from "@ruxex/artifact-tool";

const outputIndex = process.argv.indexOf("--output-dir") + 1;
const outputDirectory = process.argv[outputIndex];
if (!outputDirectory) throw new Error("--output-dir is required");

const workbook = await Workbook.create();
const sheet = workbook.worksheets.add("Smoke");
sheet.getRange("A1:B2").values = [["Name", "Count"], ["Ada", 3]];
workbook.recalculate();
await workbook.inspect({ kind: "sheet", sheetName: "Smoke" });
const workbookOutput = join(outputDirectory, "smoke.xlsx");
const workbookFile = await SpreadsheetFile.exportXlsx(workbook);
await workbookFile.save(workbookOutput);
const importedWorkbook = await SpreadsheetFile.importXlsx(await FileBlob.load(workbookOutput));
await importedWorkbook.inspect({ kind: "sheet", sheetName: "Smoke" });

const document = await Document.create({ title: "Smoke Document" });
document.addHeading("Smoke Document", 1);
document.addParagraph("Generated by the local Ruxex artifact runtime.");
document.addTable([["Format", "Status"], ["DOCX", "Ready"]]);
await document.inspect();
await document.exportDocx(join(outputDirectory, "smoke.docx"));

const presentation = Presentation.create({ title: "Smoke Presentation" });
const slide = presentation.slides.add({ layout: "title" });
slide.shapes.add({
  geometry: "textbox",
  position: { left: 72, top: 64, width: 800, height: 80 },
  text: "Smoke Presentation",
});
slide.shapes.add({
  geometry: "textbox",
  position: { left: 72, top: 150, width: 800, height: 50 },
  text: "Generated by the local Ruxex artifact runtime.",
});
slide.tables.add({
  position: { left: 72, top: 220, width: 640, height: 180 },
  rows: [["Format", "Status"], ["PPTX", "Ready"]],
});
slide.shapes.add({
  geometry: "rect",
  position: { left: 80, top: 420, width: 120, height: 60 },
});
await presentation.inspect();
const presentationOutput = join(outputDirectory, "smoke.pptx");
const presentationFile = await PresentationFile.exportPptx(presentation);
await presentationFile.save(presentationOutput);
const importedPresentation = await PresentationFile.importPptx(
  await FileBlob.load(presentationOutput),
);
await importedPresentation.inspect();
